    public int compare(anytype o1, anytype o2)
    {
        GUPPriceEngineSalesLinePriceComponentJournalLine obj1 = o1;
        GUPPriceEngineSalesLinePriceComponentJournalLine obj2 = o2;

        //only sort by price in ascending order
        return obj1.parmPrice() - obj2.parmPrice();
    }
